ALPHA, BETA = 1 / 8, 1 / 4

def update(rtt_s, rtt_d, sample, retransmitted):
    """Karn: a retransmitted segment must NOT be sampled."""
    if retransmitted:
        return rtt_s, rtt_d, rtt_s + 4 * rtt_d   # 不采样，沿用旧估计
    if rtt_s is None:                            # 第一次测量
        return sample, sample / 2, sample + 4 * (sample / 2)
    rtt_d = (1 - BETA) * rtt_d + BETA * abs(sample - rtt_s)
    rtt_s = (1 - ALPHA) * rtt_s + ALPHA * sample
    return rtt_s, rtt_d, rtt_s + 4 * rtt_d

def ip2int(s):
    a, b, c, d = (int(x) for x in s.split("."))
    return (a << 24) | (b << 16) | (c << 8) | d

def matches(ip_int, net_int, plen):
    if plen == 0:
        return True
    mask = ((1 << plen) - 1) << (32 - plen)
    return (ip_int & mask) == (net_int & mask)

def longest_prefix_match(table, dst):
    ip = ip2int(dst)
    best = None
    for prefix, plen, nexthop in table:
        if matches(ip, ip2int(prefix), plen):
            if best is None or plen > best[0]:
                best = (plen, nexthop)
    return best[1] if best else None

